'use client'

import * as React from 'react'

// The score under a place is a number a player reads, so it is a Stat. The
// place carries `data-gs-rank` and the Stat inside it carries `data-gs-value`.
import { Stat } from './stat'

import './podium.css'

/**
 * Podium: the top of a leaderboard, as the three-block shape.
 *
 * It is not a short leaderboard. A leaderboard is an ordered list a player
 * scans and scrolls; a podium is a fixed arrangement where second stands left
 * of first and third stands right of it, and where the block heights are the
 * result. Rendering that from a list component would mean a presentation
 * attribute that changes the DOM order, and the DOM order is exactly what has
 * to stay in rank order for a screen reader.
 *
 * So: DOM order is always 1, 2, 3. The visual order is CSS. Turn the
 * stylesheet off and the thing is still correct.
 *
 * Like `leaderboard`, it performs nothing. The host hands over the places
 * already ranked.
 */

export interface PodiumPlace {
  /** The player's id. Rides `data-gs-player`. */
  id: string
  /** 1, 2 or 3. The host decides; this never sorts. */
  rank: number
  /**
   * Display name. Player-supplied and therefore untrusted, so it is rendered as
   * text and never as markup.
   *
   * Follow-up: becomes an `identity` once `@gamestage/identity` ships.
   */
  name: string
  /** The number under the name. Rendered by `stat`. */
  score: number
  /** Places moved, signed. Positive is a gain. The sign is the direction. */
  delta?: number
  /** The current player's place. */
  you?: boolean
  /** The team this place stands for, when it stands for one. */
  team?: string
  /** A secondary line under the name. */
  detail?: string
}

export interface PodiumProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  /** The places, in rank order. Up to three are rendered. */
  places: PodiumPlace[]
  /** The surface's accessible name. */
  label?: string
  /** The word beside every score. */
  scoreLabel?: string
  /** Render a score as something other than the bare number. */
  formatScore?: (value: number) => string
  /** The heading of the designed empty case. */
  emptyHeading?: string
  /** The line under it. */
  emptyBody?: string
  /** The designed next step out of the empty case. */
  emptyAction?: React.ReactNode
}

/** Shared with `leaderboard` by convention, not by import: a registry item is
 *  installed on its own and may not reach into a sibling's file. */
const STATE_WORD = {
  you: 'you',
  empty: 'nothing here yet',
  up: 'moved up',
  down: 'moved down',
} as const

function movementWords(delta: number | undefined): string | null {
  if (delta === undefined || delta === 0) return null
  return `${delta > 0 ? STATE_WORD.up : STATE_WORD.down} ${Math.abs(delta)}`
}

function placeSentence(place: PodiumPlace, scoreLabel: string): string {
  const words = [String(place.rank), place.name]
  if (place.detail) words.push(place.detail)
  words.push(`${scoreLabel} ${place.score}`)
  if (place.you) words.push(STATE_WORD.you)
  const movement = movementWords(place.delta)
  if (movement) words.push(movement)
  return words.join(', ')
}

/**
 * Move every place that changed position back to where it was, then release it,
 * so the browser animates the difference over the reorder token. Under reduced
 * motion the token is `0ms` and nothing travels; the DOM order is the new order
 * either way.
 */
function useReorder(deps: readonly unknown[]) {
  const listRef = React.useRef<HTMLOListElement>(null)
  const seen = React.useRef(new Map<string, number>())

  React.useLayoutEffect(() => {
    const list = listRef.current
    if (!list) return

    const places = Array.from(list.querySelectorAll<HTMLElement>('[data-gs-player]'))
    const next = new Map<string, number>()
    const moved: Array<[HTMLElement, number]> = []

    for (const place of places) {
      const id = place.getAttribute('data-gs-player')
      if (!id) continue
      const left = place.offsetLeft
      next.set(id, left)
      const before = seen.current.get(id)
      if (before !== undefined && before !== left) moved.push([place, before - left])
    }
    seen.current = next
    if (moved.length === 0) return

    for (const [place, dx] of moved) {
      place.style.transition = 'none'
      place.style.transform = `translateX(${dx}px)`
    }
    // Commit the offset before handing the transition back, or both writes
    // coalesce and nothing animates.
    void list.offsetHeight
    for (const [place] of moved) {
      place.style.transition = ''
      place.style.transform = ''
    }
  }, deps)

  return listRef
}

export function Podium({
  places,
  label = 'podium',
  scoreLabel = 'score',
  formatScore,
  emptyHeading = 'No podium yet',
  emptyBody = 'The top three appear once the round settles.',
  emptyAction,
  className,
  ...rest
}: PodiumProps) {
  const top = places.slice(0, 3)
  const empty = top.length === 0
  const listRef = useReorder([places])

  return (
    <section
      {...rest}
      className={['gs-podium', className].filter(Boolean).join(' ')}
      data-gs-component="podium"
      data-gs-empty={empty ? 'true' : undefined}
      aria-label={empty ? `${label}, ${STATE_WORD.empty}` : label}
    >
      {empty ? (
        <div className="gs-podium__empty" data-gs-scope="podium" data-gs-part="empty">
          <span className="gs-podium__empty-glyph" data-gs-scope="podium" data-gs-part="glyph" aria-hidden="true">
            ▚
          </span>
          <p className="gs-podium__empty-heading" data-gs-scope="podium" data-gs-part="label">
            {emptyHeading}
          </p>
          <p className="gs-podium__empty-body" data-gs-scope="podium" data-gs-part="detail">
            {emptyBody}
          </p>
          {emptyAction}
        </div>
      ) : (
        <ol className="gs-podium__list" data-gs-scope="podium" data-gs-part="list" ref={listRef}>
          {top.map((place) => {
            const movement = movementWords(place.delta)
            return (
              <li
                key={place.id}
                className="gs-podium__row"
                data-gs-scope="podium" data-gs-part="row"
                data-gs-rank={place.rank}
                data-gs-player={place.id}
                data-gs-team={place.team}
                data-gs-delta={place.delta}
                data-gs-you={place.you ? 'true' : undefined}
                // The place travels when the order changes, so it is motion and
                // stops dead under reduced motion.
                data-gs-animates="motion"
              >
                {/* One sentence for a screen reader; everything visible below is
                    hidden from it, or a place announces as five things. */}
                <span className="gs-podium__sr" data-gs-scope="podium" data-gs-part="summary">
                  {placeSentence(place, scoreLabel)}
                </span>
                <span className="gs-podium__who" aria-hidden="true">
                  {/* Untrusted text, rendered as text. */}
                  <span className="gs-podium__name" data-gs-scope="podium" data-gs-part="label">
                    {place.name}
                  </span>
                  {place.detail ? (
                    <span className="gs-podium__detail" data-gs-scope="podium" data-gs-part="detail">
                      {place.detail}
                    </span>
                  ) : null}
                </span>
                <Stat
                  className="gs-podium__score"
                  kind="score"
                  value={place.score}
                  label={scoreLabel}
                  format={formatScore}
                  aria-hidden="true"
                />
                {movement ? (
                  // Colour and glyph, no travel, so it is emphasis and survives
                  // reduced motion.
                  <span
                    className="gs-podium__delta"
                    data-gs-scope="podium" data-gs-part="delta"
                    data-gs-animates="emphasis"
                    aria-hidden="true"
                  >
                    {(place.delta ?? 0) > 0 ? '▲' : '▼'}
                    {Math.abs(place.delta ?? 0)}
                  </span>
                ) : null}
                {/* The block. Its height is the rank, which is a fact the
                    stylesheet reads off data-gs-rank rather than a class. */}
                <span className="gs-podium__block gs-display-type" data-gs-scope="podium" data-gs-part="block" aria-hidden="true">
                  {place.rank}
                </span>
              </li>
            )
          })}
        </ol>
      )}
    </section>
  )
}

/* Podium. Every value comes from a token; nothing here is a literal colour. */

.gs-podium {
  display: grid;
  gap: var(--gs-space-3);
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

.gs-podium__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* DOM order is 1, 2, 3, because that is the order it must be read in. The
   arrangement is `order`, which moves nothing a screen reader or a stylesheet-
   less render sees. */
.gs-podium__list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: end;
  gap: var(--gs-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.gs-podium__row {
  display: grid;
  justify-items: center;
  gap: var(--gs-space-1);
  min-width: 0;
  text-align: center;
  transition: transform var(--gs-motion-reorder) ease-out;
}

.gs-podium__row[data-gs-rank='1'] { order: 2; }
.gs-podium__row[data-gs-rank='2'] { order: 1; }
.gs-podium__row[data-gs-rank='3'] { order: 3; }

.gs-podium__name {
  display: block;
  max-width: 100%;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  color: var(--gs-color-ink);
  /* An arbitrary-length name must not widen its column and squash the other
     two blocks. */
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gs-podium__detail {
  display: block;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The score's own label would read "score" three times across the podium. */
.gs-podium__score[data-gs-component='stat'] [data-gs-part='label'] {
  display: none;
}

.gs-podium__delta {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-positive);
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-podium__row[data-gs-delta^='-'] .gs-podium__delta {
  color: var(--gs-color-negative);
}

/* The block. Height is the rank, so the shape survives a theme changing every
   class name. */
.gs-podium__block {
  display: grid;
  place-items: center;
  width: 100%;
  font-family: var(--gs-type-display-font-family);
  font-size: var(--gs-type-display-font-size);
  font-weight: var(--gs-type-display-font-weight);
  letter-spacing: var(--gs-type-display-letter-spacing);
  color: var(--gs-color-on-bright);
  background: var(--gs-color-muted);
  border-radius: var(--gs-radius-md) var(--gs-radius-md) 0 0;
}

.gs-podium__row[data-gs-rank='1'] .gs-podium__block {
  height: var(--gs-space-12);
  background: var(--gs-color-reward);
  box-shadow: var(--gs-depth-reward);
}

.gs-podium__row[data-gs-rank='2'] .gs-podium__block {
  height: var(--gs-space-8);
  background: var(--gs-color-edge-high);
  color: var(--gs-color-ink);
}

.gs-podium__row[data-gs-rank='3'] .gs-podium__block {
  height: var(--gs-space-6);
  background: var(--gs-color-reward-base);
}

/* The player's own place is marked by a stroke and a name colour, not by the
   block colour alone, which already means the rank. */
.gs-podium__row[data-gs-you='true'] .gs-podium__block {
  outline: var(--gs-stroke-selected) solid var(--gs-color-player);
  outline-offset: calc(var(--gs-stroke-selected) * -1);
}

.gs-podium__row[data-gs-you='true'] .gs-podium__name {
  color: var(--gs-color-player);
}

/* An empty podium is a designed state, never a blank rectangle. */
.gs-podium__empty {
  display: grid;
  justify-items: center;
  gap: var(--gs-space-2);
  padding: var(--gs-space-8) var(--gs-space-4);
  text-align: center;
  background: var(--gs-color-surface);
  border: var(--gs-stroke-hairline) dashed var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
}

.gs-podium__empty-glyph {
  font-size: var(--gs-size-icon-hero);
  line-height: 1;
  color: var(--gs-color-muted);
}

.gs-podium__empty-heading {
  margin: 0;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  color: var(--gs-color-ink);
}

.gs-podium__empty-body {
  margin: 0;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink-secondary);
}
